style.css:
@-moz-document domain("youtube.com") {
/* SHARE BUTTON (Electric Cyan) */
    #top-level-buttons-computed .yt-spec-button-shape-next--tonal {
        background-color: #0d0d0d !important;
        background-image: linear-gradient(180deg, #2b3a42 0%, #10181c 50%, #05080a 100%) !important;
        color: #00f0ff !important;
        border: 2px solid #00f0ff !important;
        border-radius: 4px !important;
        box-shadow: 0 0 8px rgba(0, 240, 255, 0.55) !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        font-size: 16px !important;
        letter-spacing: 1.5px !important;
    }
    #top-level-buttons-computed .yt-spec-button-shape-next--tonal .yt-core-attributed-string,
    #top-level-buttons-computed .yt-spec-button-shape-next--tonal svg {
        color: #00f0ff !important;
        fill: #00f0ff !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
    }
    #top-level-buttons-computed .yt-spec-button-shape-next--tonal:hover {
        background-color: #002b33 !important;
        border-color: #80f8ff !important;
        box-shadow: 0 0 16px #00f0ff !important;
    }

    /* SAVE BUTTON (Electric Purple) */
    #flexible-item-buttons .yt-spec-button-shape-next--tonal {
        background-color: #14051f !important;
        background-image: linear-gradient(180deg, #3b1459 0%, #1d082e 50%, #0d0314 100%) !important;
        color: #bf00ff !important;
        border: 2px solid #bf00ff !important;
        border-radius: 4px !important;
        box-shadow: 0 0 8px rgba(191, 0, 255, 0.6) !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        font-size: 16px !important;
        letter-spacing: 1.5px !important;
    }
    #flexible-item-buttons .yt-spec-button-shape-next--tonal .yt-core-attributed-string,
    #flexible-item-buttons .yt-spec-button-shape-next--tonal svg {
        color: #bf00ff !important;
        fill: #bf00ff !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
    }
    #flexible-item-buttons .yt-spec-button-shape-next--tonal:hover {
        background-color: #290a40 !important;
        border-color: #e080ff !important;
        box-shadow: 0 0 16px #bf00ff !important;
    }

    /* THREE DOTS BUTTON (Dark Chrome + Neon Pink) */
    #actions #button-shape .yt-spec-button-shape-next--icon-button {
        background-color: #0d0d0d !important;
        background-image: linear-gradient(180deg, #3a3a3a 0%, #161616 50%, #050505 100%) !important;
        color: #ff007f !important;
        border: 2px solid #ff007f !important;
        border-radius: 4px !important;
        box-shadow: 0 0 8px rgba(255, 0, 127, 0.55) !important;
    }
    #actions #button-shape .yt-spec-button-shape-next--icon-button svg {
        color: #ff007f !important;
        fill: #ff007f !important;
    }
    #actions #button-shape .yt-spec-button-shape-next--icon-button:hover {
        background-color: #2b0016 !important;
        border-color: #ffffff !important;
        box-shadow: 0 0 15px #ff007f !important;
    }
}
